insert into public.courses (id,title,code,term,description,source_url,coverage,published) values ('data140','Probability for Data Science','DATA 140','Fall 2026','Original short-form chapter introductions for independent study alongside UC Berkeley Data 140.','https://data140.org/','One original introductory reel per textbook chapter. Full source notebooks and datasets are linked, not reproduced. These reels do not replace all chapter sections or exercises.',true) on conflict (id) do update set title=excluded.title,code=excluded.code,term=excluded.term,description=excluded.description,source_url=excluded.source_url,coverage=excluded.coverage,published=excluded.published;
insert into public.lessons (id,course_id,position,title,topic,hook,transcript,formula,video_path,duration_seconds,source_url,narrated_url,embed_url,published) values ('data140-ch01','data140',1,'The fruit lottery','Fundamentals','A random draw needs a complete guest list.',ARRAY['List every possible outcome before calculating a chance.','Choose uniformly from apple, banana, orange, and pear.','Only one of the four outcomes is orange, so its chance is one quarter.'],'P(orange) = 1/4','/videos/ch01.mp4',18,'https://data140.org/textbook/content/chapter-01/fundamentals/','https://share.descript.com/view/haD3G0cxAAw','https://share.descript.com/embed/haD3G0cxAAw',true) on conflict (id) do update set course_id=excluded.course_id,position=excluded.position,title=excluded.title,topic=excluded.topic,hook=excluded.hook,transcript=excluded.transcript,formula=excluded.formula,video_path=excluded.video_path,duration_seconds=excluded.duration_seconds,source_url=excluded.source_url,narrated_url=excluded.narrated_url,embed_url=excluded.embed_url,published=excluded.published;
insert into public.quiz_questions (id,lesson_id,prompt,options) values ('data140-ch01-check','data140-ch01','A uniform draw from four different fruits gives what chance of orange?','["1/4", "1/2"]') on conflict (id) do update set lesson_id=excluded.lesson_id,prompt=excluded.prompt,options=excluded.options;
insert into private.quiz_keys (question_id,correct_option,explanation,remediation) values ('data140-ch01-check',0,'All four fruits are equally likely. Count one orange out of four.','All four fruits are equally likely. Count one orange out of four. P(orange) = 1/4') on conflict (question_id) do update set correct_option=excluded.correct_option,explanation=excluded.explanation,remediation=excluded.remediation;
insert into public.lessons (id,course_id,position,title,topic,hook,transcript,formula,video_path,duration_seconds,source_url,narrated_url,embed_url,published) values ('data140-ch02','data140',2,'The overlap trap','Calculating Chances','Two invitations. One fruit. Don’t count it twice.',ARRAY['An event is a collection of outcomes. Two events can overlap.','Suppose P(A)=0.6, P(B)=0.5, and P(A and B)=0.2.','Add the first two probabilities, then subtract their overlap. The result is 0.9.'],'P(A or B) = 0.6 + 0.5 − 0.2 = 0.9','/videos/ch02.mp4',18,'https://data140.org/textbook/content/chapter-02/calculating-chances/','https://share.descript.com/view/GO5mzKV9urI','https://share.descript.com/embed/GO5mzKV9urI',true) on conflict (id) do update set course_id=excluded.course_id,position=excluded.position,title=excluded.title,topic=excluded.topic,hook=excluded.hook,transcript=excluded.transcript,formula=excluded.formula,video_path=excluded.video_path,duration_seconds=excluded.duration_seconds,source_url=excluded.source_url,narrated_url=excluded.narrated_url,embed_url=excluded.embed_url,published=excluded.published;
insert into public.quiz_questions (id,lesson_id,prompt,options) values ('data140-ch02-check','data140-ch02','What is the probability of A or B in this example?','["1.1", "0.9"]') on conflict (id) do update set lesson_id=excluded.lesson_id,prompt=excluded.prompt,options=excluded.options;
insert into private.quiz_keys (question_id,correct_option,explanation,remediation) values ('data140-ch02-check',1,'The overlap is included in both 0.6 and 0.5. Subtract 0.2 once.','The overlap is included in both 0.6 and 0.5. Subtract 0.2 once. P(A or B) = 0.6 + 0.5 − 0.2 = 0.9') on conflict (question_id) do update set correct_option=excluded.correct_option,explanation=excluded.explanation,remediation=excluded.remediation;
insert into public.lessons (id,course_id,position,title,topic,hook,transcript,formula,video_path,duration_seconds,source_url,narrated_url,embed_url,published) values ('data140-ch03','data140',3,'Give randomness a number','Random Variables','A random variable is a scoreboard for outcomes.',ARRAY['Imagine tossing a fair coin twice.','Let X count the heads. Its possible values are zero, one, and two.','The four equally likely outcomes give probabilities one quarter, one half, and one quarter.'],'P(X = 1) = 2/4','/videos/ch03.mp4',18,'https://data140.org/textbook/content/chapter-03/random-variables/',null,null,true) on conflict (id) do update set course_id=excluded.course_id,position=excluded.position,title=excluded.title,topic=excluded.topic,hook=excluded.hook,transcript=excluded.transcript,formula=excluded.formula,video_path=excluded.video_path,duration_seconds=excluded.duration_seconds,source_url=excluded.source_url,narrated_url=excluded.narrated_url,embed_url=excluded.embed_url,published=excluded.published;
insert into public.quiz_questions (id,lesson_id,prompt,options) values ('data140-ch03-check','data140-ch03','For two fair independent tosses, what is P(exactly one head)?','["1/2", "1/4"]') on conflict (id) do update set lesson_id=excluded.lesson_id,prompt=excluded.prompt,options=excluded.options;
insert into private.quiz_keys (question_id,correct_option,explanation,remediation) values ('data140-ch03-check',0,'HT and TH both count. Two favorable outcomes among four.','HT and TH both count. Two favorable outcomes among four. P(X = 1) = 2/4') on conflict (question_id) do update set correct_option=excluded.correct_option,explanation=excluded.explanation,remediation=excluded.remediation;
insert into public.lessons (id,course_id,position,title,topic,hook,transcript,formula,video_path,duration_seconds,source_url,narrated_url,embed_url,published) values ('data140-ch04','data140',4,'New information. New odds.','Relations Between Variables','The yellow-fruit clue changes the game.',ARRAY['A basket holds three red apples and two yellow bananas.','You learn the selected fruit is yellow. Only two outcomes remain.','Both are bananas. Given yellow, the chance of banana is one.'],'P(A | B) = P(A and B) / P(B)','/videos/ch04.mp4',18,'https://data140.org/textbook/content/chapter-04/relations-between-variables/','https://share.descript.com/view/T3RxOh25epL','https://share.descript.com/embed/T3RxOh25epL',true) on conflict (id) do update set course_id=excluded.course_id,position=excluded.position,title=excluded.title,topic=excluded.topic,hook=excluded.hook,transcript=excluded.transcript,formula=excluded.formula,video_path=excluded.video_path,duration_seconds=excluded.duration_seconds,source_url=excluded.source_url,narrated_url=excluded.narrated_url,embed_url=excluded.embed_url,published=excluded.published;
insert into public.quiz_questions (id,lesson_id,prompt,options) values ('data140-ch04-check','data140-ch04','Given yellow in this basket, what is the chance of banana?','["2/5", "1"]') on conflict (id) do update set lesson_id=excluded.lesson_id,prompt=excluded.prompt,options=excluded.options;
insert into private.quiz_keys (question_id,correct_option,explanation,remediation) values ('data140-ch04-check',1,'Condition on the clue: ignore the red apples, then count within yellow.','Condition on the clue: ignore the red apples, then count within yellow. P(A | B) = P(A and B) / P(B)') on conflict (question_id) do update set correct_option=excluded.correct_option,explanation=excluded.explanation,remediation=excluded.remediation;
insert into public.lessons (id,course_id,position,title,topic,hook,transcript,formula,video_path,duration_seconds,source_url,narrated_url,embed_url,published) values ('data140-ch05','data140',5,'At least one? Flip it.','Collections of Events','Sometimes the easiest route is the opposite event.',ARRAY['Toss a fair coin independently three times.','The only way to get no heads is TTT, with chance one eighth.','At least one head has probability one minus one eighth, or seven eighths.'],'P(at least one H) = 1 − 1/8','/videos/ch05.mp4',18,'https://data140.org/textbook/content/chapter-05/collections-of-events/',null,null,true) on conflict (id) do update set course_id=excluded.course_id,position=excluded.position,title=excluded.title,topic=excluded.topic,hook=excluded.hook,transcript=excluded.transcript,formula=excluded.formula,video_path=excluded.video_path,duration_seconds=excluded.duration_seconds,source_url=excluded.source_url,narrated_url=excluded.narrated_url,embed_url=excluded.embed_url,published=excluded.published;
insert into public.quiz_questions (id,lesson_id,prompt,options) values ('data140-ch05-check','data140-ch05','What is the chance of at least one head in three fair tosses?','["7/8", "3/8"]') on conflict (id) do update set lesson_id=excluded.lesson_id,prompt=excluded.prompt,options=excluded.options;
insert into private.quiz_keys (question_id,correct_option,explanation,remediation) values ('data140-ch05-check',0,'Start with all tails: (1/2) cubed. Subtract that from one.','Start with all tails: (1/2) cubed. Subtract that from one. P(at least one H) = 1 − 1/8') on conflict (question_id) do update set correct_option=excluded.correct_option,explanation=excluded.explanation,remediation=excluded.remediation;
insert into public.lessons (id,course_id,position,title,topic,hook,transcript,formula,video_path,duration_seconds,source_url,narrated_url,embed_url,published) values ('data140-ch06','data140',6,'Count the wins','Random Counts','A binomial counts successes under specific rules.',ARRAY['Run ten independent trials, each with success chance 0.3.','The count of successes has a binomial distribution.','Its expected count is ten times 0.3, which equals three.'],'X ~ Binomial(10, 0.3); E(X) = 3','/videos/ch06.mp4',18,'https://data140.org/textbook/content/chapter-06/random-counts/',null,null,true) on conflict (id) do update set course_id=excluded.course_id,position=excluded.position,title=excluded.title,topic=excluded.topic,hook=excluded.hook,transcript=excluded.transcript,formula=excluded.formula,video_path=excluded.video_path,duration_seconds=excluded.duration_seconds,source_url=excluded.source_url,narrated_url=excluded.narrated_url,embed_url=excluded.embed_url,published=excluded.published;
insert into public.quiz_questions (id,lesson_id,prompt,options) values ('data140-ch06-check','data140-ch06','What is the expected number of successes?','["0.3", "3"]') on conflict (id) do update set lesson_id=excluded.lesson_id,prompt=excluded.prompt,options=excluded.options;
insert into private.quiz_keys (question_id,correct_option,explanation,remediation) values ('data140-ch06-check',1,'The expected count is number of trials times chance per trial.','The expected count is number of trials times chance per trial. X ~ Binomial(10, 0.3); E(X) = 3') on conflict (question_id) do update set correct_option=excluded.correct_option,explanation=excluded.explanation,remediation=excluded.remediation;
insert into public.lessons (id,course_id,position,title,topic,hook,transcript,formula,video_path,duration_seconds,source_url,narrated_url,embed_url,published) values ('data140-ch07','data140',7,'A random-sized crowd','Poissonization','Poissonization makes some counts independent.',ARRAY['Suppose the number of visitors is Poisson with mean eight.','Independently, each visitor chooses berries with probability one quarter.','The berry count is Poisson with mean two; the other count is independent of it.'],'8 × 1/4 = 2','/videos/ch07.mp4',18,'https://data140.org/textbook/content/chapter-07/poissonization/',null,null,true) on conflict (id) do update set course_id=excluded.course_id,position=excluded.position,title=excluded.title,topic=excluded.topic,hook=excluded.hook,transcript=excluded.transcript,formula=excluded.formula,video_path=excluded.video_path,duration_seconds=excluded.duration_seconds,source_url=excluded.source_url,narrated_url=excluded.narrated_url,embed_url=excluded.embed_url,published=excluded.published;
insert into public.quiz_questions (id,lesson_id,prompt,options) values ('data140-ch07-check','data140-ch07','What is the mean of the berry count?','["2", "8"]') on conflict (id) do update set lesson_id=excluded.lesson_id,prompt=excluded.prompt,options=excluded.options;
insert into private.quiz_keys (question_id,correct_option,explanation,remediation) values ('data140-ch07-check',0,'Thin a Poisson count by multiplying its mean by the selection chance.','Thin a Poisson count by multiplying its mean by the selection chance. 8 × 1/4 = 2') on conflict (question_id) do update set correct_option=excluded.correct_option,explanation=excluded.explanation,remediation=excluded.remediation;
insert into public.lessons (id,course_id,position,title,topic,hook,transcript,formula,video_path,duration_seconds,source_url,narrated_url,embed_url,published) values ('data140-ch08','data140',8,'Average isn’t a promise','Expectation','Expectation is a weighted balance point.',ARRAY['A game pays zero tokens with chance one half and six tokens otherwise.','Multiply each payout by its probability, then add.','The expected payout is three tokens, even though the game never pays three.'],'E(X) = 0 × 0.5 + 6 × 0.5 = 3','/videos/ch08.mp4',18,'https://data140.org/textbook/content/chapter-08/expectation/',null,null,true) on conflict (id) do update set course_id=excluded.course_id,position=excluded.position,title=excluded.title,topic=excluded.topic,hook=excluded.hook,transcript=excluded.transcript,formula=excluded.formula,video_path=excluded.video_path,duration_seconds=excluded.duration_seconds,source_url=excluded.source_url,narrated_url=excluded.narrated_url,embed_url=excluded.embed_url,published=excluded.published;
insert into public.quiz_questions (id,lesson_id,prompt,options) values ('data140-ch08-check','data140-ch08','Must an expectation be a possible outcome?','["Yes", "No"]') on conflict (id) do update set lesson_id=excluded.lesson_id,prompt=excluded.prompt,options=excluded.options;
insert into private.quiz_keys (question_id,correct_option,explanation,remediation) values ('data140-ch08-check',1,'An average can lie between the actual outcomes. This game pays only zero or six.','An average can lie between the actual outcomes. This game pays only zero or six. E(X) = 0 × 0.5 + 6 × 0.5 = 3') on conflict (question_id) do update set correct_option=excluded.correct_option,explanation=excluded.explanation,remediation=excluded.remediation;
insert into public.lessons (id,course_id,position,title,topic,hook,transcript,formula,video_path,duration_seconds,source_url,narrated_url,embed_url,published) values ('data140-ch09','data140',9,'Split, then average','Conditioning Revisited','Conditioning turns one big question into smaller ones.',ARRAY['Half the days are busy with expected sales of ten baskets.','The other half are quiet with expected sales of four baskets.','Weight each conditional average by its probability: the overall expectation is seven.'],'E(X) = 0.5 × 10 + 0.5 × 4 = 7','/videos/ch09.mp4',18,'https://data140.org/textbook/content/chapter-09/conditioning-revisited/',null,null,true) on conflict (id) do update set course_id=excluded.course_id,position=excluded.position,title=excluded.title,topic=excluded.topic,hook=excluded.hook,transcript=excluded.transcript,formula=excluded.formula,video_path=excluded.video_path,duration_seconds=excluded.duration_seconds,source_url=excluded.source_url,narrated_url=excluded.narrated_url,embed_url=excluded.embed_url,published=excluded.published;
insert into public.quiz_questions (id,lesson_id,prompt,options) values ('data140-ch09-check','data140-ch09','What is the overall expected number of baskets sold?','["7", "14"]') on conflict (id) do update set lesson_id=excluded.lesson_id,prompt=excluded.prompt,options=excluded.options;
insert into private.quiz_keys (question_id,correct_option,explanation,remediation) values ('data140-ch09-check',0,'Take the average of ten and four because the two day types are equally likely.','Take the average of ten and four because the two day types are equally likely. E(X) = 0.5 × 10 + 0.5 × 4 = 7') on conflict (question_id) do update set correct_option=excluded.correct_option,explanation=excluded.explanation,remediation=excluded.remediation;
insert into public.lessons (id,course_id,position,title,topic,hook,transcript,formula,video_path,duration_seconds,source_url,narrated_url,embed_url,published) values ('data140-ch10','data140',10,'Only the present matters','Markov Chains','A Markov chain carries a very short memory.',ARRAY['A fruit cart moves between a market and a park.','For a Markov chain, next-step probabilities depend on its current state.','Once you know where it is now, earlier locations add no information about the next step.'],'P(next | present, past) = P(next | present)','/videos/ch10.mp4',18,'https://data140.org/textbook/content/chapter-10/markov-chains/',null,null,true) on conflict (id) do update set course_id=excluded.course_id,position=excluded.position,title=excluded.title,topic=excluded.topic,hook=excluded.hook,transcript=excluded.transcript,formula=excluded.formula,video_path=excluded.video_path,duration_seconds=excluded.duration_seconds,source_url=excluded.source_url,narrated_url=excluded.narrated_url,embed_url=excluded.embed_url,published=excluded.published;
insert into public.quiz_questions (id,lesson_id,prompt,options) values ('data140-ch10-check','data140-ch10','What determines the next-step distribution in a Markov chain?','["Every earlier state", "The current state"]') on conflict (id) do update set lesson_id=excluded.lesson_id,prompt=excluded.prompt,options=excluded.options;
insert into private.quiz_keys (question_id,correct_option,explanation,remediation) values ('data140-ch10-check',1,'The Markov assumption removes extra dependence on the past once the present is known.','The Markov assumption removes extra dependence on the past once the present is known. P(next | present, past) = P(next | present)') on conflict (question_id) do update set correct_option=excluded.correct_option,explanation=excluded.explanation,remediation=excluded.remediation;
insert into public.lessons (id,course_id,position,title,topic,hook,transcript,formula,video_path,duration_seconds,source_url,narrated_url,embed_url,published) values ('data140-ch11','data140',11,'Sample by wandering','Markov Chain Monte Carlo','MCMC uses movement to explore a distribution.',ARRAY['Build a Markov chain with the target distribution as stationary.','Detailed balance is a sufficient way to verify stationarity.','Convergence needs suitable conditions; successive samples are generally dependent.'],'π(i)P(i,j) = π(j)P(j,i)','/videos/ch11.mp4',18,'https://data140.org/textbook/content/chapter-11/markov-chain-monte-carlo/',null,null,true) on conflict (id) do update set course_id=excluded.course_id,position=excluded.position,title=excluded.title,topic=excluded.topic,hook=excluded.hook,transcript=excluded.transcript,formula=excluded.formula,video_path=excluded.video_path,duration_seconds=excluded.duration_seconds,source_url=excluded.source_url,narrated_url=excluded.narrated_url,embed_url=excluded.embed_url,published=excluded.published;
insert into public.quiz_questions (id,lesson_id,prompt,options) values ('data140-ch11-check','data140-ch11','Are successive MCMC samples generally independent?','["No", "Yes"]') on conflict (id) do update set lesson_id=excluded.lesson_id,prompt=excluded.prompt,options=excluded.options;
insert into private.quiz_keys (question_id,correct_option,explanation,remediation) values ('data140-ch11-check',0,'A chain moves from its current state, so nearby samples are usually dependent.','A chain moves from its current state, so nearby samples are usually dependent. π(i)P(i,j) = π(j)P(j,i)') on conflict (question_id) do update set correct_option=excluded.correct_option,explanation=excluded.explanation,remediation=excluded.remediation;
insert into public.lessons (id,course_id,position,title,topic,hook,transcript,formula,video_path,duration_seconds,source_url,narrated_url,embed_url,published) values ('data140-ch12','data140',12,'How wobbly is it?','Standard Deviation','Variance measures squared distance from the mean.',ARRAY['A random payout is zero or four, each equally likely.','Its mean is two. Each payout lies two away from the mean.','The variance is four, and the standard deviation is its square root: two.'],'Var(X) = 4; SD(X) = 2','/videos/ch12.mp4',18,'https://data140.org/textbook/content/chapter-12/standard-deviation/',null,null,true) on conflict (id) do update set course_id=excluded.course_id,position=excluded.position,title=excluded.title,topic=excluded.topic,hook=excluded.hook,transcript=excluded.transcript,formula=excluded.formula,video_path=excluded.video_path,duration_seconds=excluded.duration_seconds,source_url=excluded.source_url,narrated_url=excluded.narrated_url,embed_url=excluded.embed_url,published=excluded.published;
insert into public.quiz_questions (id,lesson_id,prompt,options) values ('data140-ch12-check','data140-ch12','What is the standard deviation of this payout?','["4", "2"]') on conflict (id) do update set lesson_id=excluded.lesson_id,prompt=excluded.prompt,options=excluded.options;
insert into private.quiz_keys (question_id,correct_option,explanation,remediation) values ('data140-ch12-check',1,'Square the deviations to get variance, then take the square root for SD.','Square the deviations to get variance, then take the square root for SD. Var(X) = 4; SD(X) = 2') on conflict (question_id) do update set correct_option=excluded.correct_option,explanation=excluded.explanation,remediation=excluded.remediation;
insert into public.lessons (id,course_id,position,title,topic,hook,transcript,formula,video_path,duration_seconds,source_url,narrated_url,embed_url,published) values ('data140-ch13','data140',13,'Do they move together?','Variance Via Covariance','Covariance reveals why variances don’t always just add.',ARRAY['For any two variables with finite second moments, include covariance.','The variance of their sum is each variance plus twice their covariance.','Independent variables have zero covariance, but the reverse need not hold.'],'Var(X+Y) = Var(X)+Var(Y)+2Cov(X,Y)','/videos/ch13.mp4',18,'https://data140.org/textbook/content/chapter-13/variance-via-covariance/',null,null,true) on conflict (id) do update set course_id=excluded.course_id,position=excluded.position,title=excluded.title,topic=excluded.topic,hook=excluded.hook,transcript=excluded.transcript,formula=excluded.formula,video_path=excluded.video_path,duration_seconds=excluded.duration_seconds,source_url=excluded.source_url,narrated_url=excluded.narrated_url,embed_url=excluded.embed_url,published=excluded.published;
insert into public.quiz_questions (id,lesson_id,prompt,options) values ('data140-ch13-check','data140-ch13','Does zero covariance always imply independence?','["No", "Yes"]') on conflict (id) do update set lesson_id=excluded.lesson_id,prompt=excluded.prompt,options=excluded.options;
insert into private.quiz_keys (question_id,correct_option,explanation,remediation) values ('data140-ch13-check',0,'Zero covariance only rules out linear association in general.','Zero covariance only rules out linear association in general. Var(X+Y) = Var(X)+Var(Y)+2Cov(X,Y)') on conflict (question_id) do update set correct_option=excluded.correct_option,explanation=excluded.explanation,remediation=excluded.remediation;
insert into public.lessons (id,course_id,position,title,topic,hook,transcript,formula,video_path,duration_seconds,source_url,narrated_url,embed_url,published) values ('data140-ch14','data140',14,'The bell emerges','The Central Limit Theorem','Averages can look normal even when individual values don’t.',ARRAY['Take a large independent, identically distributed sample.','If the population has finite, positive variance, the standardized sum approaches normal.','The standard deviation of the sample mean is population SD divided by square root of sample size.'],'SD(mean) = σ / √n','/videos/ch14.mp4',18,'https://data140.org/textbook/content/chapter-14/the-central-limit-theorem/',null,null,true) on conflict (id) do update set course_id=excluded.course_id,position=excluded.position,title=excluded.title,topic=excluded.topic,hook=excluded.hook,transcript=excluded.transcript,formula=excluded.formula,video_path=excluded.video_path,duration_seconds=excluded.duration_seconds,source_url=excluded.source_url,narrated_url=excluded.narrated_url,embed_url=excluded.embed_url,published=excluded.published;
insert into public.quiz_questions (id,lesson_id,prompt,options) values ('data140-ch14-check','data140-ch14','If n quadruples, what happens to the SD of the mean?','["It quarters", "It halves"]') on conflict (id) do update set lesson_id=excluded.lesson_id,prompt=excluded.prompt,options=excluded.options;
insert into private.quiz_keys (question_id,correct_option,explanation,remediation) values ('data140-ch14-check',1,'The denominator is square root of n. Quadrupling n doubles that denominator.','The denominator is square root of n. Quadrupling n doubles that denominator. SD(mean) = σ / √n') on conflict (question_id) do update set correct_option=excluded.correct_option,explanation=excluded.explanation,remediation=excluded.remediation;
insert into public.lessons (id,course_id,position,title,topic,hook,transcript,formula,video_path,duration_seconds,source_url,narrated_url,embed_url,published) values ('data140-ch15','data140',15,'Probability is area','Continuous Distributions','A density’s height isn’t a probability by itself.',ARRAY['For a continuous variable with a density, find probability by area.','An interval probability is the integral of the density across it.','One exact point has probability zero, even if the density there is positive.'],'P(a < X < b) = integral of f from a to b','/videos/ch15.mp4',18,'https://data140.org/textbook/content/chapter-15/continuous-distributions/',null,null,true) on conflict (id) do update set course_id=excluded.course_id,position=excluded.position,title=excluded.title,topic=excluded.topic,hook=excluded.hook,transcript=excluded.transcript,formula=excluded.formula,video_path=excluded.video_path,duration_seconds=excluded.duration_seconds,source_url=excluded.source_url,narrated_url=excluded.narrated_url,embed_url=excluded.embed_url,published=excluded.published;
insert into public.quiz_questions (id,lesson_id,prompt,options) values ('data140-ch15-check','data140-ch15','Can a positive density at x still mean P(X=x)=0?','["Yes", "No"]') on conflict (id) do update set lesson_id=excluded.lesson_id,prompt=excluded.prompt,options=excluded.options;
insert into private.quiz_keys (question_id,correct_option,explanation,remediation) values ('data140-ch15-check',0,'An individual point has zero width, hence zero area.','An individual point has zero width, hence zero area. P(a < X < b) = integral of f from a to b') on conflict (question_id) do update set correct_option=excluded.correct_option,explanation=excluded.explanation,remediation=excluded.remediation;
insert into public.lessons (id,course_id,position,title,topic,hook,transcript,formula,video_path,duration_seconds,source_url,narrated_url,embed_url,published) values ('data140-ch16','data140',16,'Stretch the scale','Transformations','Transform the axis; preserve the probability.',ARRAY['Let X be uniform between zero and one, and set Y=2X.','The possible values stretch across zero to two.','To keep total area one, the density drops to one half on that interval.'],'Y = 2X; fY(y) = 1/2 for 0 < y < 2','/videos/ch16.mp4',18,'https://data140.org/textbook/content/chapter-16/transformations/',null,null,true) on conflict (id) do update set course_id=excluded.course_id,position=excluded.position,title=excluded.title,topic=excluded.topic,hook=excluded.hook,transcript=excluded.transcript,formula=excluded.formula,video_path=excluded.video_path,duration_seconds=excluded.duration_seconds,source_url=excluded.source_url,narrated_url=excluded.narrated_url,embed_url=excluded.embed_url,published=excluded.published;
insert into public.quiz_questions (id,lesson_id,prompt,options) values ('data140-ch16-check','data140-ch16','What is the density of Y inside its interval?','["2", "1/2"]') on conflict (id) do update set lesson_id=excluded.lesson_id,prompt=excluded.prompt,options=excluded.options;
insert into private.quiz_keys (question_id,correct_option,explanation,remediation) values ('data140-ch16-check',1,'The interval doubles in width, so the density halves to preserve total area.','The interval doubles in width, so the density halves to preserve total area. Y = 2X; fY(y) = 1/2 for 0 < y < 2') on conflict (question_id) do update set correct_option=excluded.correct_option,explanation=excluded.explanation,remediation=excluded.remediation;
insert into public.lessons (id,course_id,position,title,topic,hook,transcript,formula,video_path,duration_seconds,source_url,narrated_url,embed_url,published) values ('data140-ch17','data140',17,'Two dimensions, one chance','Joint Densities','A joint density spreads probability across a plane.',ARRAY['For two continuous variables, integrate a joint density over a region.','Integrating out one coordinate gives the marginal density of the other.','For independent uniform variables on the unit square, a rectangle has probability equal to its area.'],'P(X<0.5, Y<0.5) = 0.25','/videos/ch17.mp4',18,'https://data140.org/textbook/content/chapter-17/joint-densities/',null,null,true) on conflict (id) do update set course_id=excluded.course_id,position=excluded.position,title=excluded.title,topic=excluded.topic,hook=excluded.hook,transcript=excluded.transcript,formula=excluded.formula,video_path=excluded.video_path,duration_seconds=excluded.duration_seconds,source_url=excluded.source_url,narrated_url=excluded.narrated_url,embed_url=excluded.embed_url,published=excluded.published;
insert into public.quiz_questions (id,lesson_id,prompt,options) values ('data140-ch17-check','data140-ch17','For independent uniform(0,1) X and Y, what is P(X<0.5,Y<0.5)?','["0.25", "0.5"]') on conflict (id) do update set lesson_id=excluded.lesson_id,prompt=excluded.prompt,options=excluded.options;
insert into private.quiz_keys (question_id,correct_option,explanation,remediation) values ('data140-ch17-check',0,'The lower-left square has side one half and area one quarter.','The lower-left square has side one half and area one quarter. P(X<0.5, Y<0.5) = 0.25') on conflict (question_id) do update set correct_option=excluded.correct_option,explanation=excluded.explanation,remediation=excluded.remediation;
insert into public.lessons (id,course_id,position,title,topic,hook,transcript,formula,video_path,duration_seconds,source_url,narrated_url,embed_url,published) values ('data140-ch18','data140',18,'Add the right family','The Normal and Gamma Families','Some distribution families stay familiar under addition.',ARRAY['Independent normal variables add to another normal variable.','Add their means and add their variances, not their standard deviations.','Independent gamma variables with a common rate also add, by adding their shape parameters.'],'N(1,4) + N(2,9) → N(3,13)','/videos/ch18.mp4',18,'https://data140.org/textbook/content/chapter-18/the-normal-and-gamma-families/',null,null,true) on conflict (id) do update set course_id=excluded.course_id,position=excluded.position,title=excluded.title,topic=excluded.topic,hook=excluded.hook,transcript=excluded.transcript,formula=excluded.formula,video_path=excluded.video_path,duration_seconds=excluded.duration_seconds,source_url=excluded.source_url,narrated_url=excluded.narrated_url,embed_url=excluded.embed_url,published=excluded.published;
insert into public.quiz_questions (id,lesson_id,prompt,options) values ('data140-ch18-check','data140-ch18','Using mean-variance notation, what variance does the sum have?','["5", "13"]') on conflict (id) do update set lesson_id=excluded.lesson_id,prompt=excluded.prompt,options=excluded.options;
insert into private.quiz_keys (question_id,correct_option,explanation,remediation) values ('data140-ch18-check',1,'Independence lets you add variances: four plus nine.','Independence lets you add variances: four plus nine. N(1,4) + N(2,9) → N(3,13)') on conflict (question_id) do update set correct_option=excluded.correct_option,explanation=excluded.explanation,remediation=excluded.remediation;
insert into public.lessons (id,course_id,position,title,topic,hook,transcript,formula,video_path,duration_seconds,source_url,narrated_url,embed_url,published) values ('data140-ch19','data140',19,'Package a distribution','Distributions of Sums','Moment generating functions turn sums into products.',ARRAY['The MGF of X is the expectation of exp(tX).','When it exists near zero, its derivatives at zero give moments.','For independent X and Y, the MGF of their sum is the product of their MGFs.'],'M(X+Y)(t) = MX(t) MY(t)','/videos/ch19.mp4',18,'https://data140.org/textbook/content/chapter-19/distributions-of-sums/',null,null,true) on conflict (id) do update set course_id=excluded.course_id,position=excluded.position,title=excluded.title,topic=excluded.topic,hook=excluded.hook,transcript=excluded.transcript,formula=excluded.formula,video_path=excluded.video_path,duration_seconds=excluded.duration_seconds,source_url=excluded.source_url,narrated_url=excluded.narrated_url,embed_url=excluded.embed_url,published=excluded.published;
insert into public.quiz_questions (id,lesson_id,prompt,options) values ('data140-ch19-check','data140-ch19','For independent variables, MGFs of sums combine how?','["By multiplication", "By subtraction"]') on conflict (id) do update set lesson_id=excluded.lesson_id,prompt=excluded.prompt,options=excluded.options;
insert into private.quiz_keys (question_id,correct_option,explanation,remediation) values ('data140-ch19-check',0,'The exponential of a sum factors; independence factors the expectation.','The exponential of a sum factors; independence factors the expectation. M(X+Y)(t) = MX(t) MY(t)') on conflict (question_id) do update set correct_option=excluded.correct_option,explanation=excluded.explanation,remediation=excluded.remediation;
insert into public.lessons (id,course_id,position,title,topic,hook,transcript,formula,video_path,duration_seconds,source_url,narrated_url,embed_url,published) values ('data140-ch20','data140',20,'Which parameter fits?','Approaches to Estimation','Likelihood asks which model best explains the observations.',ARRAY['Observe seven heads in ten independent tosses with a common chance p.','The likelihood is proportional to p to the seventh times (1-p) cubed.','Its maximum occurs at p=0.7. An MLE is not a posterior probability.'],'p-hat = 7/10 = 0.7','/videos/ch20.mp4',18,'https://data140.org/textbook/content/chapter-20/approaches-to-estimation/',null,null,true) on conflict (id) do update set course_id=excluded.course_id,position=excluded.position,title=excluded.title,topic=excluded.topic,hook=excluded.hook,transcript=excluded.transcript,formula=excluded.formula,video_path=excluded.video_path,duration_seconds=excluded.duration_seconds,source_url=excluded.source_url,narrated_url=excluded.narrated_url,embed_url=excluded.embed_url,published=excluded.published;
insert into public.quiz_questions (id,lesson_id,prompt,options) values ('data140-ch20-check','data140-ch20','What is the maximum likelihood estimate of p?','["0.3", "0.7"]') on conflict (id) do update set lesson_id=excluded.lesson_id,prompt=excluded.prompt,options=excluded.options;
insert into private.quiz_keys (question_id,correct_option,explanation,remediation) values ('data140-ch20-check',1,'For independent Bernoulli trials with common p, the MLE is the observed success fraction.','For independent Bernoulli trials with common p, the MLE is the observed success fraction. p-hat = 7/10 = 0.7') on conflict (question_id) do update set correct_option=excluded.correct_option,explanation=excluded.explanation,remediation=excluded.remediation;
insert into public.lessons (id,course_id,position,title,topic,hook,transcript,formula,video_path,duration_seconds,source_url,narrated_url,embed_url,published) values ('data140-ch21','data140',21,'Let evidence update belief','The Beta and the Binomial','Beta and binomial make an especially convenient pair.',ARRAY['Start with a Beta(2,2) prior for a coin’s head probability.','Observe three heads and one tail in independent trials given p.','The posterior is Beta(5,3); its mean, and next-head probability, is five eighths.'],'Beta(2,2) → Beta(5,3)','/videos/ch21.mp4',18,'https://data140.org/textbook/content/chapter-21/the-beta-and-the-binomial/',null,null,true) on conflict (id) do update set course_id=excluded.course_id,position=excluded.position,title=excluded.title,topic=excluded.topic,hook=excluded.hook,transcript=excluded.transcript,formula=excluded.formula,video_path=excluded.video_path,duration_seconds=excluded.duration_seconds,source_url=excluded.source_url,narrated_url=excluded.narrated_url,embed_url=excluded.embed_url,published=excluded.published;
insert into public.quiz_questions (id,lesson_id,prompt,options) values ('data140-ch21-check','data140-ch21','What is the posterior predictive probability of the next head?','["5/8", "3/4"]') on conflict (id) do update set lesson_id=excluded.lesson_id,prompt=excluded.prompt,options=excluded.options;
insert into private.quiz_keys (question_id,correct_option,explanation,remediation) values ('data140-ch21-check',0,'Add heads to the first shape and tails to the second, then use 5/(5+3).','Add heads to the first shape and tails to the second, then use 5/(5+3). Beta(2,2) → Beta(5,3)') on conflict (question_id) do update set correct_option=excluded.correct_option,explanation=excluded.explanation,remediation=excluded.remediation;
insert into public.lessons (id,course_id,position,title,topic,hook,transcript,formula,video_path,duration_seconds,source_url,narrated_url,embed_url,published) values ('data140-ch22','data140',22,'The best squared-error guess','Prediction','Conditional expectation is a prediction rule.',ARRAY['When X is observed, predict Y using its conditional mean.','Among predictors based on X, this minimizes expected squared error, assuming finite second moments.','Total variance splits into the variance of conditional means and the average conditional variance.'],'Var(Y) = Var(E[Y|X]) + E[Var(Y|X)]','/videos/ch22.mp4',18,'https://data140.org/textbook/content/chapter-22/prediction/',null,null,true) on conflict (id) do update set course_id=excluded.course_id,position=excluded.position,title=excluded.title,topic=excluded.topic,hook=excluded.hook,transcript=excluded.transcript,formula=excluded.formula,video_path=excluded.video_path,duration_seconds=excluded.duration_seconds,source_url=excluded.source_url,narrated_url=excluded.narrated_url,embed_url=excluded.embed_url,published=excluded.published;
insert into public.quiz_questions (id,lesson_id,prompt,options) values ('data140-ch22-check','data140-ch22','Which predictor minimizes expected squared error?','["Always zero", "E[Y|X]"]') on conflict (id) do update set lesson_id=excluded.lesson_id,prompt=excluded.prompt,options=excluded.options;
insert into private.quiz_keys (question_id,correct_option,explanation,remediation) values ('data140-ch22-check',1,'Use the average of Y among outcomes consistent with the observed X.','Use the average of Y among outcomes consistent with the observed X. Var(Y) = Var(E[Y|X]) + E[Var(Y|X)]') on conflict (question_id) do update set correct_option=excluded.correct_option,explanation=excluded.explanation,remediation=excluded.remediation;
insert into public.lessons (id,course_id,position,title,topic,hook,transcript,formula,video_path,duration_seconds,source_url,narrated_url,embed_url,published) values ('data140-ch23','data140',23,'A cloud of variables','Multivariate Normal RVs','Joint normality is stronger than normal marginals.',ARRAY['A jointly normal vector has normally distributed linear combinations.','Its mean vector and covariance matrix describe its distribution.','For jointly normal components, zero covariance implies independence.'],'Joint normal + zero covariance ⇒ independence','/videos/ch23.mp4',18,'https://data140.org/textbook/content/chapter-23/multivariate-normal-rvs/',null,null,true) on conflict (id) do update set course_id=excluded.course_id,position=excluded.position,title=excluded.title,topic=excluded.topic,hook=excluded.hook,transcript=excluded.transcript,formula=excluded.formula,video_path=excluded.video_path,duration_seconds=excluded.duration_seconds,source_url=excluded.source_url,narrated_url=excluded.narrated_url,embed_url=excluded.embed_url,published=excluded.published;
insert into public.quiz_questions (id,lesson_id,prompt,options) values ('data140-ch23-check','data140-ch23','Does zero covariance imply independence for jointly normal components?','["Yes", "No"]') on conflict (id) do update set lesson_id=excluded.lesson_id,prompt=excluded.prompt,options=excluded.options;
insert into private.quiz_keys (question_id,correct_option,explanation,remediation) values ('data140-ch23-check',0,'Joint normality is the extra condition that makes this implication valid.','Joint normality is the extra condition that makes this implication valid. Joint normal + zero covariance ⇒ independence') on conflict (question_id) do update set correct_option=excluded.correct_option,explanation=excluded.explanation,remediation=excluded.remediation;
insert into public.lessons (id,course_id,position,title,topic,hook,transcript,formula,video_path,duration_seconds,source_url,narrated_url,embed_url,published) values ('data140-ch24','data140',24,'The best straight-line guess','Simple Linear Regression','Regression balances association and spread.',ARRAY['The best linear predictor uses slope Cov(X,Y) divided by Var(X), if Var(X)>0.','Equivalently, slope is correlation times SD(Y) divided by SD(X).','This is a linear least-squares prediction, not automatically a causal effect.'],'slope = r × SD(Y) / SD(X)','/videos/ch24.mp4',18,'https://data140.org/textbook/content/chapter-24/simple-linear-regression/',null,null,true) on conflict (id) do update set course_id=excluded.course_id,position=excluded.position,title=excluded.title,topic=excluded.topic,hook=excluded.hook,transcript=excluded.transcript,formula=excluded.formula,video_path=excluded.video_path,duration_seconds=excluded.duration_seconds,source_url=excluded.source_url,narrated_url=excluded.narrated_url,embed_url=excluded.embed_url,published=excluded.published;
insert into public.quiz_questions (id,lesson_id,prompt,options) values ('data140-ch24-check','data140-ch24','If r=0.5, SD(Y)=4, SD(X)=2, what is the slope?','["4", "1"]') on conflict (id) do update set lesson_id=excluded.lesson_id,prompt=excluded.prompt,options=excluded.options;
insert into private.quiz_keys (question_id,correct_option,explanation,remediation) values ('data140-ch24-check',1,'Multiply 0.5 by four divided by two.','Multiply 0.5 by four divided by two. slope = r × SD(Y) / SD(X)') on conflict (question_id) do update set correct_option=excluded.correct_option,explanation=excluded.explanation,remediation=excluded.remediation;
insert into public.lessons (id,course_id,position,title,topic,hook,transcript,formula,video_path,duration_seconds,source_url,narrated_url,embed_url,published) values ('data140-ch25','data140',25,'More clues. One prediction.','Multiple Regression','Multiple regression combines several predictors.',ARRAY['Arrange predictors into a vector X with covariance matrix Σ.','When Σ is invertible, the best linear slope vector solves Σβ=Cov(X,Y).','Correlated predictors must be handled together; separate simple slopes usually won’t work.'],'β = Σ⁻¹ Cov(X,Y)','/videos/ch25.mp4',18,'https://data140.org/textbook/content/chapter-25/multiple-regression/',null,null,true) on conflict (id) do update set course_id=excluded.course_id,position=excluded.position,title=excluded.title,topic=excluded.topic,hook=excluded.hook,transcript=excluded.transcript,formula=excluded.formula,video_path=excluded.video_path,duration_seconds=excluded.duration_seconds,source_url=excluded.source_url,narrated_url=excluded.narrated_url,embed_url=excluded.embed_url,published=excluded.published;
insert into public.quiz_questions (id,lesson_id,prompt,options) values ('data140-ch25-check','data140-ch25','Can correlated predictors generally be fitted by combining separate simple slopes?','["No", "Yes"]') on conflict (id) do update set lesson_id=excluded.lesson_id,prompt=excluded.prompt,options=excluded.options;
insert into private.quiz_keys (question_id,correct_option,explanation,remediation) values ('data140-ch25-check',0,'Each multiple-regression coefficient accounts for the other predictors.','Each multiple-regression coefficient accounts for the other predictors. β = Σ⁻¹ Cov(X,Y)') on conflict (question_id) do update set correct_option=excluded.correct_option,explanation=excluded.explanation,remediation=excluded.remediation;
